<script setup lang="ts">
import PmsFormDialog from './PmsFormDialog.vue';
import PmsTableControls from './PmsTableControls.vue';
import {ref,onMounted,computed} from 'vue';const props=defineProps<{csrf?:string;permissions:string[]}>();const search=ref(''),tablePage=ref(1),tableSize=ref(10);const paged=computed(()=>tableSize.value<0?shown.value:shown.value.slice((tablePage.value-1)*tableSize.value,tablePage.value*tableSize.value));const shown=computed(()=>data.value?.data?.filter((u:any)=>(u.name+' '+u.email).toLowerCase().includes(search.value.toLowerCase()))||[]);const data=ref<any>(null),editor=ref<any>(null),busy=ref(false),error=ref(''),message=ref('');const can=(k:string)=>props.permissions.includes('*')||props.permissions.includes(k);
async function api(path='',method='GET',body?:any){const r=await fetch('/pms/api/employees'+path,{method,headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':props.csrf||''},body:body?JSON.stringify(body):undefined});const d=await r.json();if(!r.ok)throw Error(Object.values(d.errors||{}).flat().join(' ')||d.message||'Unable to complete this action.');return d;}
async function load(){try{data.value=await api();}catch(e){error.value=(e as Error).message;}}
async function edit(row?:any){error.value='';if(!row){editor.value={name:'',surname:'',designation:'',email:'',password:'',status:1,dept_id:'',role_id:''};return;}busy.value=true;try{const d=(await api('/'+row.id)).data;editor.value={...d,dept_id:d.departments[0]?.id||'',role_id:d.roles[0]?.id||''};}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function remove(u:any){if(!confirm('Remove '+u.name+' from PMS?'))return;busy.value=true;error.value='';try{const r=await api('/'+u.id,'DELETE');message.value=r.message;await load();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function save(){busy.value=true;error.value='';try{const d=await api(editor.value.id?'/'+editor.value.id:'','POST',editor.value);message.value=d.message;editor.value=null;await load();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}onMounted(load);
</script>
<template><p v-if="error" class="notice admin-error" role="alert">{{error}}</p><p v-if="message" class="notice" role="status">{{message}}</p><PmsFormDialog v-if="editor" title="Employee" wide centered @close="editor=null"><form class="pms-reference-form" @submit.prevent="save"><label>Name <span class="text-danger">*</span><input placeholder="Enter name" v-model="editor.name" required maxlength="255"></label><label>Surname<input placeholder="Enter surname" v-model="editor.surname" maxlength="255"></label><label>Email <span class="text-danger">*</span><input placeholder="Enter email" type="email" v-model="editor.email" required maxlength="255"></label><label v-if="!editor.id">Password<input type="password" v-model="editor.password" required minlength="8" autocomplete="new-password"></label><label>Designation<input placeholder="Enter designation" v-model="editor.designation" required maxlength="255"></label><label>Role<select v-model.number="editor.role_id" required><option value="" disabled>Select role</option><option v-for="r in data?.roles" :key="r.id" :value="r.id">{{r.role_name}}</option></select></label><label>Department<select v-model.number="editor.dept_id" required><option value="" disabled>Select department</option><option v-for="d in data?.departments" :key="d.id" :value="d.id">{{d.dept_name}}</option></select></label><label>Status<select v-model.number="editor.status"><option :value="1">Active</option><option :value="0">Inactive</option></select></label><div class="editor-actions"><button class="button primary" :disabled="busy">{{busy?'Saving...':editor.id?'Save changes':'Create'}}</button><button type="button" class="button" @click="editor=null">Cancel</button></div></form></PmsFormDialog><div class="pms-table-card"><div class="pms-table-heading"><button v-if="can('employee-add')" class="button primary" @click="edit()"><i aria-hidden="true" class="ti ti-circle-plus"></i>Create</button></div><PmsTableControls :total="shown.length" v-model:page="tablePage" v-model:size="tableSize" v-model:search="search"/><table class="pms-table"><thead><tr><th scope="col">ID</th><th scope="col">Image</th><th scope="col">Name</th><th scope="col">Email</th><th scope="col">Department</th><th scope="col">Role</th><th scope="col">Status</th><th scope="col">Actions</th></tr></thead><tbody><tr v-for="u in paged" :key="u.id"><td>{{u.id}}</td><td><img v-if="u.profile_img" class="pms-project-image" :src="u.profile_img" alt=""><span v-else class="pms-project-image">{{u.name.charAt(0)}}</span></td><td>{{u.name}} {{u.surname}}</td><td>{{u.email}}</td><td>{{u.departments.map((d:any)=>d.dept_name).join(', ')}}</td><td>{{u.roles.map((r:any)=>r.role_name).join(', ')}}</td><td><span class="pms-status-badge">{{Number(u.status)===1?'Active':'Inactive'}}</span></td><td><div class="pms-project-actions"><button v-if="can('employee-edit')" class="action-edit" aria-label="Edit employee" @click="edit(u)"><i class="ti ti-edit"></i></button><button v-if="can('employee-trash')" class="action-delete" aria-label="Delete employee" :disabled="busy" @click="remove(u)"><i class="ti ti-trash"></i></button></div></td></tr><tr v-if="!shown.length"><td colspan="8">No employees found.</td></tr></tbody></table><PmsTableControls footer :total="shown.length" v-model:page="tablePage" v-model:size="tableSize"/></div></template>